# --- Encoder-decoder structure for news content and neighborhood encoding ---
import torch
import torch.nn as nn

class Encoder(nn.Module):
    def __init__(self, input_dim, embed_dim, num_heads, num_layers):
        super(Encoder, self).__init__()
        self.content_embedding = nn.Linear(input_dim, embed_dim)
        self.type_embedding = nn.Embedding(10, embed_dim) # Assuming max 10 node types
        self.pos_encoder = nn.Parameter(torch.randn(1, 512, embed_dim))
        encoder_layer = nn.TransformerEncoderLayer(d_model=embed_dim, nhead=num_heads)
        self.transformer_encoder = nn.TransformerEncoder(encoder_layer, num_layers=num_layers)

    def forward(self, x, node_types):
        x = self.content_embedding(x) + self.type_embedding(node_types) + self.pos_encoder[:, :x.size(1), :]
        return self.transformer_encoder(x)

class Decoder(nn.Module):
    def __init__(self, embed_dim, output_dim):
        super(Decoder, self).__init__()
        self.fc = nn.Sequential(
            nn.Linear(embed_dim, embed_dim // 2),
            nn.ReLU(),
            nn.Linear(embed_dim // 2, output_dim)
        )

    def forward(self, x):
        # Global average pooling over the sequence dimension
        x = x.mean(dim=1)
        return self.fc(x)

# --- Heterogeneous neighbor sampling and RWR-based strategies ---
def rwr_strategy(graph, start_node, restart_prob=0.15, max_steps=100):
    """
    Calculates proximity scores using Random Walk with Restart.
    Assumes 'graph' is an adjacency list or similar structure.
    """
    scores = {start_node: 1.0}
    for _ in range(max_steps):
        new_scores = {node: 0.0 for node in graph}
        for node, score in scores.items():
            neighbors = graph.get(node, [])
            if not neighbors:
                new_scores[start_node] += score
                continue

            # Distribute probability
            for neighbor in neighbors:
                new_scores[neighbor] += (1 - restart_prob) * (score / len(neighbors))
            new_scores[start_node] += restart_prob * score
        scores = new_scores
    return scores

def heterogeneous_neighbor_sampling(graph, target_node, num_samples, node_types):
    """
    Samples neighbors based on RWR scores, ensuring heterogeneous representation.
    """
    scores = rwr_strategy(graph, target_node)
    # Sort neighbors by RWR score
    sorted_neighbors = sorted(scores.items(), key=lambda x: x[1], reverse=True)

    sampled = []
    for node, _ in sorted_neighbors:
        if len(sampled) >= num_samples:
            break
        if node != target_node:
            sampled.append(node)

    return sampled

# --- Type-specific transformation matrices ---
class TypeSpecificTransformationMatrix(nn.Module):
    def __init__(self, node_type_dims, embed_dim):
        super(TypeSpecificTransformationMatrix, self).__init__()
        # Create a dictionary of linear projections to map each type to embed_dim
        self.transformations = nn.ModuleDict({
            str(node_type): nn.Linear(dim, embed_dim) 
            for node_type, dim in node_type_dims.items()
        })

    def forward(self, x, node_type):
        # Select the specific matrix for the node type and project the features
        node_type_str = str(node_type.item()) if node_type.dim() == 0 else str(node_type[0].item())
        return self.transformations[node_type_str](x)

# --- Multi-modal semantic aggregation ---
def multi_modal_aggregation(content_embeddings, visual_embeddings, structural_embeddings, pos_encoder, type_embeddings):
    """
    Aggregates multi-modal features by concatenating content, visual, and structural 
    embeddings with positional and type information.
    """
    # Concatenate content, visual, and structural embeddings along the feature dimension (dim=-1)
    fused_features = torch.cat([content_embeddings, visual_embeddings, structural_embeddings], dim=-1)

    # Add positional and type embeddings to the fused representation
    # Assuming pos_encoder and type_embeddings are broadcastable to the fused_features shape
    aggregated_output = fused_features + pos_encoder + type_embeddings

    return aggregated_output

